// Step 01: Normalize Client Onboarding Payload & E.164 Phone
const rawInput = $input.first().json.body || $input.first().json || {};
const isEmptyTrigger = Object.keys(rawInput).length === 0;

const body = isEmptyTrigger ? {
  clientName: 'Apex Consumer Brands NG',
  contactName: 'Adaeze Nwosu',
  email: 'Adaeze.Nwosu@ApexBrands.ng',
  phone: '08091122334',
  packageSigned: 'Retainer - Brand Design, Web & Paid Media',
  missingAssets: ['Brand Guidelines PDF', 'Meta Business Manager Partner ID', 'Product High-Res Photos'],
  depositStatus: 'CONFIRMED'
} : rawInput;

const rawPhone = String(body.phone || '08091122334').replace(/[^0-9+]/g, '');
let e164Phone = rawPhone;
if (rawPhone.startsWith('0') && rawPhone.length === 11) {
  e164Phone = '+234' + rawPhone.slice(1);
} else if (!rawPhone.startsWith('+') && rawPhone.length >= 10) {
  e164Phone = '+' + rawPhone;
}

return [{
  json: {
    onboardingId: `ONB-${Date.now()}`,
    clientName: String(body.clientName || 'Client').trim(),
    contactName: String(body.contactName || 'Client Lead').trim(),
    email: String(body.email || '').toLowerCase().trim(),
    phone: e164Phone,
    packageSigned: String(body.packageSigned || 'Agency Retainer').trim(),
    missingAssets: Array.isArray(body.missingAssets) ? body.missingAssets : ['Brand Assets', 'Ad Account Access'],
    depositStatus: String(body.depositStatus || 'CONFIRMED'),
    triggeredAt: new Date().toISOString()
  }
}];

// Step 02: Provision Google Drive Workspace & Project Folders
const data = $input.first().json;
const slug = data.clientName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
return [{
  json: {
    ...data,
    driveWorkspaceStatus: 'PROVISIONED',
    driveRootFolderUrl: `https://drive.google.com/drive/folders/msl-client-${slug}`,
    subfoldersCreated: [
      '01_Brand_Assets_And_Logos',
      '02_Creative_Briefs_And_Copy',
      '03_Ad_Account_Access_And_Tracking',
      '04_Weekly_Performance_Reports'
    ]
  }
}];

// Step 03: Generate Structured Asset Chaser (WhatsApp + Email) & Internal PM Task
const data = $input.first().json;
const assetList = data.missingAssets.map((a, i) => `${i + 1}. ${a}`).join('\n');
const waMessage = `Hi ${data.contactName}, welcome aboard! Your dedicated client workspace for ${data.clientName} is ready (${data.driveRootFolderUrl}). To keep kickoff on schedule, please upload these remaining items:\n${assetList}`;
const waUrl = `https://wa.me/${data.phone.replace('+', '')}?text=${encodeURIComponent(waMessage)}`;

return [{
  json: {
    ...data,
    chaserStatus: 'READY_FOR_DISPATCH',
    oneClickWhatsAppChaserUrl: waUrl,
    whatsappChaserPreview: waMessage,
    emailChaserSubject: `Kickoff Workspace & Asset Checklist — ${data.clientName}`,
    followupSchedule: 'Day 1 (Immediate) -> Day 3 (48h Reminder) -> Day 5 (Account Manager Escalation)'
  }
}];

// Step 04: Internal Slack / PM Kickoff Notification
const data = $input.first().json;
return [{
  json: {
    pmSyncStatus: 'PROJECT_BOARD_CREATED',
    slackChannelAlert: `[New Client Onboarded] ${data.clientName} (${data.packageSigned}) | Drive: ${data.driveRootFolderUrl} | Missing Assets: ${data.missingAssets.join(', ')}`
  }
}];

const err = $input.first().json;
return [{
  json: {
    circuitBreakerStatus: 'ALERT_DISPATCHED',
    errorSummary: err?.execution?.error?.message || 'Unhandled onboarding workflow exception.'
  }
}];
